{
  "name": "todos-feature",
  "watches": [
    {
      "name": "empty-state",
      "scenarios": [
        "features/todos.feature:No todos hides main and footer"
      ]
    },
    {
      "name": "creating-todos",
      "scenarios": [
        "features/todos.feature:Create a new todo",
        "features/todos.feature:Empty input is ignored"
      ]
    },
    {
      "name": "toggle-all",
      "scenarios": [
        "features/todos.feature:Mark all as complete toggles all todos",
        "features/todos.feature:Clear completed resets toggle-all"
      ]
    },
    {
      "name": "individual-items",
      "scenarios": [
        "features/todos.feature:Toggle a single todo",
        "features/todos.feature:Double-click activates editing mode",
        "features/todos.feature:Destroy button removes a todo"
      ]
    },
    {
      "name": "editing",
      "scenarios": [
        "features/todos.feature:Save edit on Enter",
        "features/todos.feature:Save edit on blur",
        "features/todos.feature:Empty edit destroys the todo",
        "features/todos.feature:Escape discards edit"
      ]
    },
    {
      "name": "counter",
      "scenarios": [
        "features/todos.feature:Active todo count is singular",
        "features/todos.feature:Active todo count is pluralized"
      ]
    },
    {
      "name": "clear-completed",
      "scenarios": [
        "features/todos.feature:Clear completed button removes completed todos",
        "features/todos.feature:Clear completed is hidden when no completed todos"
      ]
    },
    {
      "name": "persistence",
      "scenarios": [
        "features/todos.feature:Todos persist across reload"
      ]
    },
    {
      "name": "routing",
      "scenarios": [
        "features/todos.feature:All route shows all todos",
        "features/todos.feature:Active route shows only active todos",
        "features/todos.feature:Completed route shows only completed todos",
        "features/todos.feature:Marking todo complete in filtered view hides it"
      ]
    }
  ]
}

